package com.autoops.workflow.validation;import com.autoops.workflow.entity.WorkflowStep;import org.springframework.stereotype.Service;import java.util.*;@Service public class WorkflowGraphValidator{public void validate(List<WorkflowStep> steps){if(steps.isEmpty())throw new IllegalArgumentException("Workflow requires a step");Set<Long> ids=new HashSet<>();steps.forEach(s->{if(s.getId()!=null)ids.add(s.getId());});for(var s:steps){for(Long n:List.of(s.getSuccessNextStepId(),s.getFailureNextStepId()))if(n!=null&&!ids.contains(n))throw new IllegalArgumentException("Edge points outside workflow");}detectCycles(steps);}private void detectCycles(List<WorkflowStep>s){Map<Long,WorkflowStep>m=new HashMap<>();s.forEach(x->{if(x.getId()!=null)m.put(x.getId(),x);});Set<Long>vis=new HashSet<>(),stack=new HashSet<>();for(Long id:m.keySet())dfs(id,m,vis,stack);}private void dfs(Long id,Map<Long,WorkflowStep>m,Set<Long>v,Set<Long>st){if(st.contains(id))throw new IllegalArgumentException("Workflow cycles are not allowed");if(!v.add(id))return;st.add(id);var x=m.get(id);if(x!=null){if(x.getSuccessNextStepId()!=null)dfs(x.getSuccessNextStepId(),m,v,st);if(x.getFailureNextStepId()!=null)dfs(x.getFailureNextStepId(),m,v,st);}st.remove(id);}}
